import{_ as t,c as p,aU as o,a as e}from"./chunks/framework.DP-R0N-M.js";const c=JSON.parse('{"title":"谈谈python","description":"","frontmatter":{},"headers":[],"relativePath":"note/my-diary/谈谈python.md","filePath":"note/my-diary/谈谈python.md","lastUpdated":1762599044000}'),n={name:"note/my-diary/谈谈python.md"};function i(r,a,y,l,s,h){return e(),p("div",null,[...a[0]||(a[0]=[o('<h1 id="谈谈python" tabindex="-1">谈谈python <a class="header-anchor" href="#谈谈python" aria-label="Permalink to &quot;谈谈python&quot;">​</a></h1><p>我是学java的，对于python之前有学过一点，不过还是给我劝退了， 有一说一，py语法确实是简单，同样的功能，py需要1行，java可能需要20行，这就是很多开发人员说java比较重的原因。都感觉啰嗦。 但是我觉得，这个只是小问题，主要是python语法太简洁，显得中规中矩的java太笨重了。java想的话，无非是封装一套工具api也可以实现。</p><p>但是python缺点也是非常的多， 而且有对我而言直接给他打入死刑的原因。</p><ol><li>包管理器太烂，和java比差的太远，对于我而言，一个优秀的编程语言包管理器是必备的。</li><li>语法写的真难受，强制缩进，没有大括号。如果没有IDE的话真的没办开发，这样的设计真的很优雅么？？？？？Look at my eyes</li><li>api的入参出参对于我来说完全黑盒，不知道要传什么，返回什么，这个是最忍不了的。参考隔壁的java， 任何一个第三方的sdk库，点进去一看就知道该api需要什么入参，如何组装，返回什么对象。一目了然。</li><li>弱类型编程语言，问题不能提前暴漏，非得运行才报错。我个人感觉，后台语言都应该是强类型的，搞毛弱类型啊， 只顾自己当时写起来爽，重构火葬场。再次参考java，十几年的jsp项目都照样都能维护到现在，没办法，java就是稳如老狗，虽然很占内存， 企业开发稳定才是硬道理，内存才值几个钱。</li></ol><p>但是呢，py在ai领域确实很强，都在用py，其他语言真的赶不上，没办法，生态这东西不是说赶上就赶上的。你要硬要用java开发ai 也可以，就是你会发现很吃力，网上一搜都是python，几乎找不到java的。慢慢的，你也搞不下去了。</p><p>虽然我对py有很多的吐槽，没办法，打不过就加入呗。开始学习python</p>',6)])])}const m=t(n,[["render",i]]);export{c as __pageData,m as default};
